import math
import random
import subprocess
import sys
from datetime import datetime, timedelta
from decimal import Decimal, Inexact, localcontext
from fractions import Fraction
from more_itertools import numeric_range

random.seed(1247)
cases = [(2**53, 2**53 + 8, .25), (-2**53, -2**53 - 8, -.25)]
for _ in range(2000):
    start = random.uniform(-100, 100)
    step = random.choice((-1, 1)) * 10 ** random.uniform(-3, 1)
    cases.append((start, start + random.randrange(50) * step, step))
for start, stop, step in cases:
    r = numeric_range(start, stop, step)
    expected = []
    for i in range(1000):
        item = start + i * step
        if not (item < stop if step > 0 else item > stop):
            break
        expected.append(item)
    else:
        raise AssertionError('oracle bound exceeded')
    assert len(r) == len(expected), (r, len(r), len(expected))
    for i, item in enumerate(expected):
        assert item in r and r.index(item) == expected.index(item)
        assert r[i] == item
        for v in (math.nextafter(item, -math.inf), math.nextafter(item, math.inf)):
            assert (v in r) == (v in expected), (r, v)
for start in (2**53 + 1, -(2**53 + 1), Fraction(2**53 + 1)):
    for step in (-2, -1, 1, 2, Fraction(1, 2)):
        r = numeric_range(start, start + 10 * step, step)
        items = list(r)
        for v in map(float, items):
            assert (v in r) == (v in items), (r, v)
            if v in items:
                assert r.index(v) == items.index(v), (r, v)
            else:
                try:
                    r.index(v)
                except ValueError:
                    pass
                else:
                    raise AssertionError((r, v))
assert len(numeric_range(-1e308, 1e308, 1e308)) == 2
assert len(numeric_range(0., 1e-322, 5e-324)) == 20
assert numeric_range(0., 2**53 + 8, 1.).index(float(2**53)) == 2**53
r = numeric_range(0., 1e308, 1.)
assert r.index(0.) == 0 and r.index(1.) == 1
assert r._len > sys.maxsize
try:
    len(r)
except OverflowError:
    pass
else:
    raise AssertionError('len overflow was not reported')
for bound in (math.inf, math.nan):
    try:
        len(numeric_range(0, bound, 1))
    except ValueError:
        pass
    else:
        raise AssertionError('nonfinite length did not preserve ValueError')
r = numeric_range(-1e308, 1e308, 10**308)
assert r.index(0.) == 1 and 1e307 not in r
try:
    r.index(1e307)
except ValueError:
    pass
else:
    raise AssertionError('nonmember accepted')
for args in [(0, 100, 3), (Fraction(0), Fraction(1), Fraction(1, 7)), (datetime(2020, 1, 1), datetime(2020, 1, 3), timedelta(hours=5))]:
    r = numeric_range(*args)
    items = list(r)
    assert len(r) == len(items)
    assert all(r.index(item) == i and item in r for i, item in enumerate(items))
r = numeric_range(datetime(9999, 12, 30), datetime(9999, 12, 31), timedelta(days=2))
assert len(r) == 1 and r.index(datetime(9999, 12, 30)) == 0
assert datetime(9999, 12, 30) in r

# Compare Decimal results, exceptions and context signals to the original code.
source = subprocess.run(['git', 'show', '74d0a3756a5f95469f73d6f39589833fd0023f22:more_itertools/more.py'], text=True, capture_output=True, check=True).stdout
namespace = {'__name__': 'more_itertools._baseline', '__package__': 'more_itertools'}
exec(compile(source, '<baseline more.py>', 'exec'), namespace)
original = namespace['numeric_range']
for args, value in [((Decimal('1'), Decimal('2'), Decimal('.3')), Decimal('1.6')), ((Decimal(0), 1., Decimal('.123456789')), Decimal(0)), ((Decimal('1'), Decimal('2'), Decimal('.3')), 1.6)]:
    for operation in (lambda r: len(r), lambda r: r.index(value), lambda r: value in r):
        results = []
        for factory in (original, numeric_range):
            with localcontext() as context:
                context.prec = 5
                context.traps[Inexact] = True
                context.clear_flags()
                try:
                    outcome = operation(factory(*args))
                except Exception as exc:
                    outcome = type(exc)
                results.append((outcome, dict(context.flags)))
        assert results[0] == results[1], (args, value, results)
print('PASS: 2,002 float sequence oracles, mixed integer/Fraction queries, duplicate first indices, extreme scales, nonfinite bounds, datetime limits, and baseline Decimal context comparisons.')
PY
